import type { ImageSourcePropType } from 'react-native'

// Metro requires static string literals, so each style photo needs its own
// require() call — this file just gives callers a single lookup by style id.
// Keep in sync with TRY_ON_STYLES in @cutty/types and the images generated by
// apps/admin/scripts/generate-style-photos.mjs.

// Styles tagged 'male' or 'female' in TRY_ON_STYLES only ever show in their
// one matching booking-gallery section, so they need just one photo each.
export const STYLE_IMAGES: Record<string, ImageSourcePropType> = {
  buzz: require('../assets/styles/buzz.jpg'),
  crew: require('../assets/styles/crew.jpg'),
  'taper-fade': require('../assets/styles/taper-fade.jpg'),
  'skin-fade': require('../assets/styles/skin-fade.jpg'),
  pompadour: require('../assets/styles/pompadour.jpg'),
  quiff: require('../assets/styles/quiff.jpg'),
  'slick-back': require('../assets/styles/slick-back.jpg'),
  waves: require('../assets/styles/waves.jpg'),
  'man-bun': require('../assets/styles/man-bun.jpg'),
  pixie: require('../assets/styles/pixie.jpg'),
  'blunt-bob': require('../assets/styles/blunt-bob.jpg'),
  'shoulder-layers': require('../assets/styles/shoulder-layers.jpg'),
  'box-braids': require('../assets/styles/box-braids.jpg'),
  'knotless-braids': require('../assets/styles/knotless-braids.jpg'),
  'senegalese-twists': require('../assets/styles/senegalese-twists.jpg'),
  'faux-locs': require('../assets/styles/faux-locs.jpg'),
  'bantu-knots': require('../assets/styles/bantu-knots.jpg'),
  'lace-front-wig': require('../assets/styles/lace-front-wig.jpg'),
  'bob-wig': require('../assets/styles/bob-wig.jpg'),
  'curly-wig': require('../assets/styles/curly-wig.jpg'),
  'silk-press': require('../assets/styles/silk-press.jpg'),
}

// Styles tagged 'unisex' show in BOTH the Men and Women booking-gallery
// sections, so each needs a men and a women photo — otherwise the "wrong"
// gender's photo would show up in one of the two sections.
export const UNISEX_STYLE_IMAGES: Record<string, { men: ImageSourcePropType; women: ImageSourcePropType }> = {
  'curly-top': {
    men: require('../assets/styles/curly-top-men.jpg'),
    women: require('../assets/styles/curly-top-women.jpg'),
  },
  afro: {
    men: require('../assets/styles/afro-men.jpg'),
    women: require('../assets/styles/afro-women.jpg'),
  },
  locs: {
    men: require('../assets/styles/locs-men.jpg'),
    women: require('../assets/styles/locs-women.jpg'),
  },
  cornrows: {
    men: require('../assets/styles/cornrows-men.jpg'),
    women: require('../assets/styles/cornrows-women.jpg'),
  },
  curtains: {
    men: require('../assets/styles/curtains-men.jpg'),
    women: require('../assets/styles/curtains-women.jpg'),
  },
}

/**
 * Resolves the right thumbnail for a style card given which booking-gallery
 * section ("Men" or "Women") it's being shown in — a unisex style shows its
 * men or women variant to match, a male/female style always shows its one photo.
 */
export function getStyleImage(styleId: string, section: 'male' | 'female'): ImageSourcePropType | undefined {
  const variant = UNISEX_STYLE_IMAGES[styleId]
  if (variant) return section === 'male' ? variant.men : variant.women
  return STYLE_IMAGES[styleId]
}
